import React from 'react';
import '../styles/Home.css';

function Home() {
  return (
    <section id="home" className="hero">
      <div className="hero-content">
        <h1>Welcome to Studio Besut</h1>
        <p>Your Premium Camera Self-Studio Experience</p>
        <button className="hero-button">Start Booking</button>
      </div>
    </section>
  );
}

export default Home;
